import express from "express";
import path from "path";
import { GoogleGenAI } from "@google/genai";
import dotenv from "dotenv";

dotenv.config();

const app = express();
const PORT = 3000;

app.use(express.json());

let ai: GoogleGenAI | null = null;
function getGeminiClient(): GoogleGenAI | null {
  if (!ai) {
    const apiKey = process.env.GEMINI_API_KEY;
    if (apiKey && apiKey !== "MY_GEMINI_API_KEY" && apiKey.length > 5) {
      ai = new GoogleGenAI({
        apiKey,
        httpOptions: {
          headers: {
            "User-Agent": "aistudio-build",
          },
        },
      });
    }
  }
  return ai;
}

// Endpoint for personalized Neuro-Cognitive coaching advice
app.post("/api/neuro-coaching", async (req, res) => {
  try {
    const { stats, recentGame } = req.body;
    const client = getGeminiClient();

    if (!client) {
      return res.json({
        advice: "Excelente esfuerzo. Para potenciar tu memoria de trabajo, intenta llevar mentalmente la cuenta de cuántas fichas de cada número han sido jugadas.",
        keyFocus: "Memoria de trabajo y conteo de pintas",
        recommendedDifficulty: "Adaptativo Neuro-AI",
      });
    }

    const prompt = `Actúa como un neuropsicólogo experto en neuro-estimulación cognitiva mediante juegos tradicionales como el dominó.
Analiza las siguientes métricas del jugador:
- Precisión de decisiones: ${stats?.accuracy ?? 85}%
- Tiempo promedio por jugada: ${stats?.avgSpeedSeconds ?? 3.2}s
- Índice de memoria de trabajo: ${stats?.workingMemoryScore ?? 78}/100
- Lógica construccional: ${stats?.spatialLogicScore ?? 82}/100
- Racha diaria: ${stats?.streakDays ?? 1} días
- Última partida: ${recentGame ? `${recentGame.won ? 'Victoria' : 'Derrota'} con ${recentGame.points} pts` : 'Iniciando entrenamiento'}

Devuelve un JSON con:
{
  "advice": "Un consejo motivador y técnico (máximo 25 palabras) enfocado en memoria espacial, de trabajo o lógica construccional.",
  "keyFocus": "Área clave a reforzar (máximo 4 palabras)",
  "recommendedDifficulty": "Adaptativo Neuro-AI"
}`;

    const response = await client.models.generateContent({
      model: "gemini-3.6-flash",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
      },
    });

    const text = response.text || "{}";
    const data = JSON.parse(text);
    return res.json(data);
  } catch (err) {
    console.error("Error in neuro-coaching API:", err);
    return res.json({
      advice: "Mantén un ritmo constante. Visualizar las puntas del tablero entrena tu capacidad de flexibilidad cognitiva y planeación.",
      keyFocus: "Planeación de aperturas",
      recommendedDifficulty: "Adaptativo Neuro-AI",
    });
  }
});

async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const { createServer: createViteServer } = await import("vite");
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
